function formatAiQuotaMessage(message, params = {}) {
  return message.replace(/\{([A-Za-z0-9_]+)\}/g, (_, name) => String(params[name] ?? `{${name}}`));
}

function validateAiQuotaCatalogs(catalogs) {
  const reference = Object.keys(catalogs.en).sort();
  const errors = [];
  for (const [locale, catalog] of Object.entries(catalogs)) {
    const keys = Object.keys(catalog).sort();
    const missing = reference.filter((key) => !keys.includes(key));
    const extra = keys.filter((key) => !reference.includes(key));
    if (missing.length) errors.push(`${locale} missing: ${missing.join(", ")}`);
    if (extra.length) errors.push(`${locale} extra: ${extra.join(", ")}`);
    for (const key of reference.filter((candidate) => candidate in catalog)) {
      const params = (value) => [...value.matchAll(/\{([A-Za-z0-9_]+)\}/g)].map((match) => match[1]).sort().join(",");
      if (params(catalogs.en[key]) !== params(catalog[key])) errors.push(`${locale} parameters differ: ${key}`);
    }
  }
  if (errors.length) throw new Error(errors.join("\n"));
  return true;
}

function createAiQuotaLocalization(catalogs) {
  const supported = Object.freeze({
    en: { direction: "ltr", format: "en-US" },
    ar: { direction: "rtl", format: "ar-EG-u-nu-latn-ca-gregory" },
    fr: { direction: "ltr", format: "fr-FR" },
    de: { direction: "ltr", format: "de-DE" },
  });
  const announcements = Object.freeze({
    en: "Language changed to English",
    ar: "تم تغيير اللغة إلى العربية",
    fr: "Langue changée en français",
    de: "Sprache auf Deutsch geändert",
  });
  const reverseEnglish = new Map(Object.entries(catalogs.en).map(([key, value]) => [value, key]));
  let locale = supported[document.documentElement.lang] ? document.documentElement.lang : "en";
  const textOriginal = new WeakMap();
  const textRendered = new WeakMap();
  const textRenderedLocale = new WeakMap();
  const attributeOriginal = new WeakMap();
  const attributeRendered = new WeakMap();
  const attributeRenderedLocale = new WeakMap();
  let observer;

  validateAiQuotaCatalogs(catalogs);
  const t = (key, params) => formatAiQuotaMessage(catalogs[locale]?.[key] ?? catalogs.en[key] ?? key, params);
  const translateCore = (source) => {
    if (locale === "en" || !source) return source;
    const key = reverseEnglish.get(source);
    if (key && catalogs[locale]?.[key]) return catalogs[locale][key];
    const exact = AI_QUOTA_EXACT[locale]?.[source];
    if (exact) return exact;
    let result = source;
    for (const [pattern, replacement] of AI_QUOTA_PATTERNS[locale] ?? []) {
      if (pattern.test(result)) { result = result.replace(pattern, replacement); break; }
    }
    for (const [pattern, replacement] of AI_QUOTA_EXTRA_PATTERNS[locale] ?? []) {
      result = result.replace(pattern, replacement);
    }
    const counts = AI_QUOTA_COUNT_WORDS[locale] ?? {};
    const countFn = locale === "ar"
      ? (forms) => (value) => aiQuotaArabicCount(Number(value), forms)
      : (forms) => (value) => aiQuotaCount(locale, Number(value), forms);
    if (counts.readings) result = result.replace(/\b(\d+) readings\b/g, (_, value) => countFn(counts.readings)(value));
    if (counts.refreshes) result = result.replace(/\b(\d+) refreshes\b/g, (_, value) => countFn(counts.refreshes)(value));
    if (counts.requests) result = result.replace(/\b(\d+) requests\b/g, (_, value) => countFn(counts.requests)(value));
    if (counts.keys) result = result.replace(/\b(\d+) keys\b/g, (_, value) => countFn(counts.keys)(value));
    for (const [from, to] of AI_QUOTA_FRAGMENTS[locale] ?? []) {
      const escaped = from.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      result = /^[A-Za-z ]+$/.test(from) ? result.replace(new RegExp(`\\b${escaped}\\b`, "g"), to) : result.replaceAll(from, to);
    }
    for (const [pattern, replacement] of AI_QUOTA_TIME_PATTERNS[locale] ?? []) {
      result = result.replace(pattern, replacement);
    }
    return result;
  };

  function translateTextNode(node) {
    if (!node.parentElement || node.parentElement.closest("script, style, code, [data-i18n-skip]")) return;
    const current = node.nodeValue;
    if (current === textRendered.get(node) && textRenderedLocale.get(node) === locale) return;
    if (locale === "en") {
      const original = textOriginal.get(node);
      if (original !== undefined && current !== original) node.nodeValue = original;
      textRendered.set(node, original ?? current);
      textRenderedLocale.set(node, locale);
      return;
    }
    // `current` is only safe to treat as the English source the first time
    // this node is ever translated (textOriginal has no entry yet, meaning
    // it's still showing the pristine server-rendered/template English).
    // Once a cached original exists, always translate FROM that cached
    // value, never from `current` — `current` could be the PREVIOUS
    // non-English locale's rendered text (e.g. this node still shows
    // Arabic and we're switching straight to German, with English never
    // back on screen in between), and no rule table can translate Arabic
    // into German. Re-using `current` as the source in that case used to
    // both fail the translation and permanently overwrite the true English
    // original with the stale non-English text, corrupting every later
    // switch for this node too — not just this one.
    const original = textOriginal.has(node) ? textOriginal.get(node) : current;
    textOriginal.set(node, original);
    const leading = original.match(/^\s*/)?.[0] ?? "";
    const trailing = original.match(/\s*$/)?.[0] ?? "";
    const core = original.slice(leading.length, original.length - trailing.length);
    const translated = `${leading}${translateCore(core)}${trailing}`;
    if (translated !== current) node.nodeValue = translated;
    textRendered.set(node, translated);
    textRenderedLocale.set(node, locale);
  }

  const translatedAttributes = ["aria-label", "aria-valuetext", "title", "placeholder", "alt"];
  function translateElementAttributes(element) {
    if (element.closest("[data-i18n-skip]")) return;
    let originals = attributeOriginal.get(element);
    let rendered = attributeRendered.get(element);
    if (!originals) { originals = new Map(); attributeOriginal.set(element, originals); }
    if (!rendered) { rendered = new Map(); attributeRendered.set(element, rendered); }
    for (const name of translatedAttributes) {
      if (!element.hasAttribute(name)) continue;
      const current = element.getAttribute(name);
      if (current === rendered.get(name) && attributeRenderedLocale.get(element) === locale) continue;
      if (locale === "en") {
        const original = originals.get(name);
        if (original !== undefined && current !== original) element.setAttribute(name, original);
        rendered.set(name, original ?? current);
      } else {
        // Same fix as translateTextNode above: prefer the already-cached
        // original over `current`, which may be the previous non-English
        // locale's rendered value rather than English.
        const original = originals.has(name) ? originals.get(name) : current;
        originals.set(name, original);
        const translated = translateCore(original);
        if (translated !== current) element.setAttribute(name, translated);
        rendered.set(name, translated);
      }
    }
    attributeRenderedLocale.set(element, locale);
  }

  function apply(root = document) {
    const element = root.nodeType === Node.ELEMENT_NODE ? root : root.documentElement;
    translateElementAttributes(element);
    element.querySelectorAll("*").forEach(translateElementAttributes);
    const walker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) translateTextNode(walker.currentNode);
  }

  function setLocale(next, options = {}) {
    if (!supported[next]) next = "en";
    locale = next;
    document.documentElement.lang = next;
    document.documentElement.dir = supported[next].direction;
    if (options.persist !== false) {
      try { localStorage.setItem(AI_QUOTA_LANGUAGE_STORAGE_KEY, next); } catch { /* In-session switching still works. */ }
    }
    document.querySelectorAll(".language-select").forEach((select) => { select.value = next; });
    apply();
    document.dispatchEvent(new CustomEvent("aiquotelanguagechange", { detail: { locale: next } }));
  }

  function observe() {
    observer?.disconnect();
    observer = new MutationObserver((records) => {
      for (const record of records) {
        if (record.type === "characterData") translateTextNode(record.target);
        else if (record.type === "attributes") translateElementAttributes(record.target);
        else for (const node of record.addedNodes) {
          if (node.nodeType === Node.TEXT_NODE) translateTextNode(node);
          else if (node.nodeType === Node.ELEMENT_NODE) apply(node);
        }
      }
    });
    observer.observe(document.body, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: translatedAttributes });
  }

  const formatLocale = () => supported[locale].format;
  return Object.freeze({
    t, apply, observe, setLocale, get locale() { return locale; }, get direction() { return supported[locale].direction; },
    announcement: (next) => announcements[next] ?? announcements.en,
    number: (value, options = {}) => new Intl.NumberFormat(formatLocale(), { numberingSystem: "latn", ...options }).format(value),
    date: (value, options = {}) => new Intl.DateTimeFormat(formatLocale(), { calendar: "gregory", numberingSystem: "latn", ...options }).format(value),
    translate: translateCore,
  });
}


/* crypto-vault.js */
const encoder = new TextEncoder();
const decoder = new TextDecoder();

// Deliberately kept as the app's old name ("quota-local"), not renamed to
// AI Quota Meter — this is the literal localStorage key every user's
// encrypted vault is already stored under. Renaming it would not touch their
// real data at all; it would just make the app look under a different key,
// find nothing, and appear to have deleted every account they've added. See
// app.js for the same reasoning applied to the vault's sibling keys.
const VAULT_STORAGE_KEY = "quota-local:encrypted-vault:v1";
const PBKDF2_ITERATIONS = 600_000;

function bytesToBase64(bytes) {
  let value = "";
  for (const byte of bytes) value += String.fromCharCode(byte);
  return btoa(value);
}

function base64ToBytes(value) {
  const decoded = atob(value);
  return Uint8Array.from(decoded, (character) => character.charCodeAt(0));
}

async function deriveKey(passphrase, salt, iterations = PBKDF2_ITERATIONS, extractable = false) {
  const material = await crypto.subtle.importKey(
    "raw",
    encoder.encode(passphrase),
    "PBKDF2",
    false,
    ["deriveKey"],
  );
  return crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations, hash: "SHA-256" },
    material,
    { name: "AES-GCM", length: 256 },
    extractable,
    ["encrypt", "decrypt"],
  );
}

async function encryptWithKey(value, key) {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ciphertext = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv },
    key,
    encoder.encode(JSON.stringify(value)),
  );
  return { iv: bytesToBase64(iv), ciphertext: bytesToBase64(new Uint8Array(ciphertext)) };
}

async function decryptWithKey(record, key) {
  const plaintext = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: base64ToBytes(record.iv) },
    key,
    base64ToBytes(record.ciphertext),
  );
  return JSON.parse(decoder.decode(plaintext));
}

async function encryptVaultData(value, passphrase, options = {}) {
  if (typeof passphrase !== "string" || passphrase.length < 12) {
    throw new Error("Use a master passphrase of at least 12 characters.");
  }
  const iterations = options.iterations ?? PBKDF2_ITERATIONS;
  const salt = options.salt ?? crypto.getRandomValues(new Uint8Array(16));
  const key = await deriveKey(passphrase, salt, iterations);
  const encrypted = await encryptWithKey(value, key);
  return {
    version: 1,
    kdf: "PBKDF2-HMAC-SHA256",
    iterations,
    salt: bytesToBase64(salt),
    ...encrypted,
  };
}

async function decryptVaultData(record, passphrase) {
  if (!record || record.version !== 1 || record.kdf !== "PBKDF2-HMAC-SHA256") {
    throw new Error("Unsupported encrypted vault format.");
  }
  try {
    const key = await deriveKey(passphrase, base64ToBytes(record.salt), record.iterations);
    return await decryptWithKey(record, key);
  } catch {
    throw new Error("Incorrect passphrase or damaged vault.");
  }
}

class LocalEncryptedVault {
  constructor(storage = localStorage) {
    this.storage = storage;
    this.key = null;
    this.record = null;
    this.data = null;
  }

  exists() {
    return this.storage.getItem(VAULT_STORAGE_KEY) !== null;
  }

  isUnlocked() {
    return this.key !== null;
  }

  async create(passphrase, initialData = { accounts: [], preferences: {} }) {
    const record = await encryptVaultData(initialData, passphrase);
    this.storage.setItem(VAULT_STORAGE_KEY, JSON.stringify(record));
    this.record = record;
    this.key = await deriveKey(passphrase, base64ToBytes(record.salt), record.iterations);
    this.data = structuredClone(initialData);
    return structuredClone(this.data);
  }

  async unlock(passphrase) {
    const serialized = this.storage.getItem(VAULT_STORAGE_KEY);
    if (!serialized) throw new Error("No encrypted vault exists on this browser.");
    const record = JSON.parse(serialized);
    const data = await decryptVaultData(record, passphrase);
    this.record = record;
    this.key = await deriveKey(passphrase, base64ToBytes(record.salt), record.iterations);
    this.data = data;
    return structuredClone(data);
  }

  async save(data) {
    if (!this.key || !this.record) throw new Error("Unlock the encrypted vault first.");
    const encrypted = await encryptWithKey(data, this.key);
    this.record = { ...this.record, ...encrypted };
    this.storage.setItem(VAULT_STORAGE_KEY, JSON.stringify(this.record));
    this.data = structuredClone(data);
    return structuredClone(this.data);
  }

  lock() {
    this.key = null;
    this.record = null;
    this.data = null;
  }

  // Exports a raw AES key derived from the given passphrase, for an opt-in
  // "remember this device" flow. This never touches this.key (which stays
  // non-extractable for normal operation) and never stores the passphrase
  // itself — only a one-way-derived, vault-scoped key.
  async exportRememberKey(passphrase) {
    if (!this.record) throw new Error("Unlock the vault first.");
    const extractableKey = await deriveKey(passphrase, base64ToBytes(this.record.salt), this.record.iterations, true);
    const raw = await crypto.subtle.exportKey("raw", extractableKey);
    return bytesToBase64(new Uint8Array(raw));
  }

  async unlockWithRememberKey(base64Key) {
    const serialized = this.storage.getItem(VAULT_STORAGE_KEY);
    if (!serialized) throw new Error("No encrypted vault exists on this browser.");
    const record = JSON.parse(serialized);
    let key;
    try {
      key = await crypto.subtle.importKey("raw", base64ToBytes(base64Key), "AES-GCM", false, ["encrypt", "decrypt"]);
    } catch {
      throw new Error("Invalid remembered key.");
    }
    const data = await decryptWithKey(record, key);
    this.record = record;
    this.key = key;
    this.data = data;
    return structuredClone(data);
  }

  exportEncrypted() {
    const serialized = this.storage.getItem(VAULT_STORAGE_KEY);
    if (!serialized) throw new Error("No encrypted vault to export.");
    return serialized;
  }

  importEncrypted(serialized) {
    const record = JSON.parse(serialized);
    if (!record || record.version !== 1 || !record.salt || !record.iv || !record.ciphertext) {
      throw new Error("This is not a valid AI Quota Meter encrypted vault.");
    }
    this.storage.setItem(VAULT_STORAGE_KEY, JSON.stringify(record));
    this.lock();
  }

  clear() {
    this.storage.removeItem(VAULT_STORAGE_KEY);
    this.lock();
  }
}


/* deepseek-usage.js */
function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = "";
  let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (quoted) {
      if (character === '"' && text[index + 1] === '"') {
        field += '"';
        index += 1;
      } else if (character === '"') {
        quoted = false;
      } else {
        field += character;
      }
    } else if (character === '"') {
      quoted = true;
    } else if (character === ",") {
      row.push(field);
      field = "";
    } else if (character === "\n") {
      row.push(field.replace(/\r$/, ""));
      if (row.some((value) => value.length > 0)) rows.push(row);
      row = [];
      field = "";
    } else {
      field += character;
    }
  }
  row.push(field.replace(/\r$/, ""));
  if (row.some((value) => value.length > 0)) rows.push(row);
  return rows;
}

function normalizedHeader(value) {
  return String(value).trim().toLowerCase().replace(/^\ufeff/, "");
}

function summarizeDeepSeekAmountCsv(text) {
  const rows = parseCsv(text);
  if (rows.length < 2) throw new Error("The DeepSeek amount CSV has no usage rows.");
  const headers = rows[0].map(normalizedHeader);
  const column = (name) => headers.indexOf(name);
  const typeIndex = column("type");
  const amountIndex = column("amount");
  if (typeIndex < 0 || amountIndex < 0) throw new Error("Choose the DeepSeek amount CSV containing type and amount columns.");
  const keyNameIndex = column("api_key_name");
  const maskedKeyIndex = column("api_key");
  const modelIndex = column("model");
  const dateIndexes = [column("start_time_iso"), column("end_time_iso"), column("utc_date")].filter((index) => index >= 0);
  const keys = new Map();
  const models = new Set();
  const dates = [];
  let totalTokens = 0;
  let totalRequests = 0;

  for (const row of rows.slice(1)) {
    const type = String(row[typeIndex] ?? "").trim().toLowerCase();
    const amount = Number(String(row[amountIndex] ?? "").trim());
    if (!Number.isFinite(amount) || amount < 0 || amount > Number.MAX_SAFE_INTEGER) continue;
    const keyName = String(row[keyNameIndex] ?? row[maskedKeyIndex] ?? "Unnamed key").trim() || "Unnamed key";
    const current = keys.get(keyName) ?? { name: keyName, tokens: 0, requests: 0 };
    if (type === "request_count" || type === "request") {
      current.requests += amount;
      totalRequests += amount;
    } else if (["output_tokens", "input_cache_hit_tokens", "input_cache_miss_tokens", "prompt_token", "prompt_cache_hit_token", "prompt_cache_miss_token", "response_token"].includes(type)) {
      current.tokens += amount;
      totalTokens += amount;
    } else {
      continue;
    }
    keys.set(keyName, current);
    const model = String(row[modelIndex] ?? "").trim();
    if (model) models.add(model);
    for (const index of dateIndexes) {
      const timestamp = Date.parse(row[index]);
      if (Number.isFinite(timestamp)) dates.push(timestamp);
    }
  }
  if (keys.size === 0) throw new Error("No recognized DeepSeek usage rows were found in this CSV.");
  dates.sort((a, b) => a - b);
  return {
    totalTokens,
    totalRequests,
    keys: [...keys.values()].sort((a, b) => b.tokens - a.tokens || b.requests - a.requests).slice(0, 100),
    models: [...models].sort(),
    periodStart: dates.length ? new Date(dates[0]).toISOString() : null,
    periodEnd: dates.length ? new Date(dates.at(-1)).toISOString() : null,
  };
}


/* demo-data.js */
// Builds a plausible refresh ledger for the demo: a quiet morning, a working
// session, then the reading the card is showing right now. Offsets are minutes
// before "now"; each entry lists the used percent per window at that moment.
function demoLedger(now, resets, entries) {
  return {
    version: 1,
    samples: entries.map(([offsetMinutes, values]) => ({
      t: now.getTime() + offsetMinutes * 60_000,
      w: Object.fromEntries(Object.entries(values).map(([id, used]) => [id, { u: used, r: now.getTime() + resets[id] * 60_000 }])),
    })),
  };
}

function demoBalanceLedger(now, entries) {
  return {
    version: 1,
    samples: entries.map(([offsetMinutes, total]) => ({ t: now.getTime() + offsetMinutes * 60_000, b: total, c: "USD" })),
  };
}

